head.script:
scwin.uploadIdx = 0; // upload 컴포넌트 추가할 index
scwin.curRowIdx = -1; // oncellClick 발생한 rowIndex

scwin.onpageload = function () {
	generator1.hide();
};

scwin.onpageunload = function () {

};

// 행 추가 버튼 클릭
scwin.trigger1_onclick = function (e) {

	const rowIndex = dataList1.getRowCount();
	console.log(rowIndex);
	dataList1.insertData(rowIndex, ["test", "20260401235959", "업로드", "", "전송"]); // 업로드 및 전송 버튼있는 행 추가

	const info = {
		inputType: "button"
	}

	gridView1.setCellInputType(rowIndex, "col3", info);
	gridView1.setCellInputType(rowIndex, "col5", info);

	generator1.insertChild(scwin.uploadIdx); // upload 컴포넌트 추가
	scwin.uploadIdx++;
};


// 업로드, 전송 버튼 클릭
scwin.gridView1_oncellclick = function (rowIndex, columnIndex, columnId) {
    scwin.curRowIdx = rowIndex;

	if (columnId === "col3") { // 업로드 버튼 클릭
		const clickUpload = generator1.getChild(rowIndex, "upload1");

		if (clickUpload) {
			clickUpload.dom.fakeinput.click(); // 업로드 컴포넌트 클릭
		} else {
			console.error("Element with ID " + clickUpload.id + " not found.");
		}
	} else if (columnId === "col5") { // 전송 버튼 클릭
        const rowData = dataList1.getRowJSON(rowIndex);
        const upload = generator1.getChild(rowIndex, "upload1");

        // Object.entries를 사용하여 key와 value를 동시에 추출
        Object.entries(rowData).forEach(([key, value]) => {
            upload.addParam(key, value);
        });
		upload.submit(); // 업로드 전송

		console.log("업로드");
	}
};

// 파일 정보 출력
scwin.upload1_onInputValueChange = function (fileName) {
	dataList1.setCellData(scwin.curRowIdx, "col4", fileName); //gridView 셀에 업로드 파일 이름 추가
};
